import json,glob
def longest_ident_asst(msgs):
    asst=[]
    for m in msgs:
        if m.get('role')=='assistant':
            c=m.get('content')
            if isinstance(c,list): txt=' '.join(str(x.get('text','') if isinstance(x,dict) else x) for x in c)
            else: txt=str(c)
            t=txt.strip()
            if t: asst.append(t)
    best=1;run=1
    for j in range(1,len(asst)):
        if asst[j]==asst[j-1]: run+=1; best=max(best,run)
        else: run=1
    return best if asst else 0
rows=[]
for rj in sorted(glob.glob('task_*/result.json')):
    d=json.load(open(rj)); tid=d['task_id']; rew=d['reward']
    try: msgs=json.load(open(rj.replace('result.json','messages.json')))
    except: continue
    rows.append((tid,rew,longest_ident_asst(msgs)))
rows.sort(key=lambda r:-r[2])
for tid,rew,b in rows:
    if b>=3: print(f'{tid} rew={rew} longest_identical_assistant_run={b}')
